var body = ($input.first().json && $input.first().json.body) ? $input.first().json.body : ($input.first().json || {});
var jd = String(body.job_description || '');
var company = String(body.company || '');
var email = String(body.recipient || body.contact_email || '').toLowerCase().trim();
var score = 0;
var reasons = [];
// Email domain vs company (only if provided)
var emailDomain = '';
var at = email.indexOf('@'); if (at !== -1) emailDomain = email.slice(at + 1);
var freeProviders = ['gmail.com','yahoo.com','hotmail.com','outlook.com','live.com','aol.com','icloud.com','protonmail.com','mail.com','yandex.com','gmx.com','ymail.com'];
var isFree = false;
for (var i = 0; i < freeProviders.length; i++) { if (emailDomain === freeProviders[i]) { isFree = true; break; } }
if (isFree) { score += 25; reasons.push('Free-mail domain (' + emailDomain + ') used'); }
// Description length
var words = jd ? jd.split(/\s+/).filter(function (w) { return w.length > 0; }).length : 0;
if (words === 0) { score += 20; reasons.push('No job description provided'); }
else if (words < 100) { score += 15; reasons.push('Job description under 100 words (' + words + ')'); }
// Ghost-job / vague language signals
var hay = (jd + ' ' + company).toLowerCase();
var vagueKw = ['fast-paced environment','wear many hats','rockstar','ninja','unlimited earning','be your own boss','no experience needed','immediate start','urgent hiring','work from home opportunity','flexible schedule guaranteed'];
for (var v = 0; v < vagueKw.length; v++) { if (hay.indexOf(vagueKw[v]) !== -1) { score += 8; reasons.push('Vague/ghost phrasing: ' + vagueKw[v]); } }
// Scam keywords -> strong signal
var scamKw = ['training fee','equipment purchase','bank details','bank account number','national id','processing fee','registration fee','pay a deposit','western union','send money','upfront payment','activation fee'];
for (var k = 0; k < scamKw.length; k++) { if (hay.indexOf(scamKw[k]) !== -1) { score += 40; reasons.push('Scam keyword detected: ' + scamKw[k]); } }
if (score > 100) score = 100;
if (score < 0) score = 0;
var groqBody = { model: 'llama-3.3-70b-versatile', temperature: 0.2, max_tokens: 120, messages: [ { role: 'system', content: 'You extract keywords. Return ONLY a comma-separated list of the 5 most important keywords or short key phrases from the job description, no numbering, no extra text.' }, { role: 'user', content: 'Extract the top 5 most important keywords from this job description: ' + jd.slice(0, 4000) } ] };
return [{ json: { job_description: jd, word_count: words, ghost_score: score, ghost_reasons: reasons.join('; ') || 'No suspicious signals detected', groqBody: groqBody } }];

var meta = $('Ghost Job Scorer').first().json || {};
var jd = String(meta.job_description || '');
var groq = $input.first().json || {};
var raw = '';
try { raw = groq.choices[0].message.content || ''; } catch (e) { raw = ''; }
raw = String(raw).trim();
// Parse comma / newline separated keyword list
var top = [];
if (raw) {
  var parts = raw.split(/[,\n]+/);
  for (var i = 0; i < parts.length; i++) {
    var t = parts[i].replace(/^[0-9]+[).\-\s]+/, '').replace(/^[\-\*\s]+/, '').trim();
    if (t) top.push(t);
  }
}
top = top.slice(0, 5);
// Keyword frequency map over common industry terms
var terms = ['engineering','industrial','process','optimization','supply chain','logistics','operations','management','lean','quality','safety','inventory','procurement','vendor','risk','data','analysis','project','manufacturing','production','compliance','maintenance','planning','continuous improvement','six sigma','automation'];
var lc = jd.toLowerCase();
var freq = {};
for (var j = 0; j < terms.length; j++) {
  var term = terms[j];
  var count = 0; var idx = lc.indexOf(term);
  while (idx !== -1) { count++; idx = lc.indexOf(term, idx + term.length); }
  if (count > 0) freq[term] = count;
}
var response = { ghost_score: meta.ghost_score, ghost_reasons: meta.ghost_reasons, word_count: meta.word_count, top_keywords: top, keyword_frequency: freq };
return [{ json: response }];
